parameters.functionCode:
// Find Due Diligence tasks that need processing
const tasks = $input.first().json.result || [];
console.log(`Checking ${tasks.length} tasks for Due Diligence processing`);

// Look for tasks with "Due Diligence:" in title
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Check if it's a Due Diligence task
  if (title.toLowerCase().includes('due diligence:')) {
    // Extract company name from title
    const companyName = title.replace(/due diligence:\s*/i, '').trim();

    // Check if Due Diligence is already completely done
    if (description.includes('🤖 COMPLETE DUE DILIGENCE REPORT GENERATED')) {
      console.log(`Task ${task.id} already has complete Due Diligence - skipping`);
      continue;
    }

    // Get all section names that are already approved
    const approvedSectionMatches = description.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/g) || [];
    const approvedSectionNames = approvedSectionMatches.map(match => {
      const nameMatch = match.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/);
      return nameMatch ? nameMatch[1] : '';
    }).filter(name => name);

    console.log(`Task ${task.id}: ${approvedSectionNames.length}/20 sections completed`);
    console.log(`Approved sections: ${approvedSectionNames.join(', ')}`);

    // Define all sections in order
    const allSections = [
      "Introduction & Engagement Context", "Methodology & Reliability Levels", "Company Overview",
      "Business Model & Unit Economics", "Products & Technology", "Target Market & Competitive Set",
      "Financials", "Cash, Burn, Runway", "Revenue Quality & Client Cohorts",
      "Partnerships & Ecosystem", "Intellectual Property", "Legal & Regulatory",
      "Governance & Board Effectiveness", "Capital Structure & Dilution", "Risk Matrix & Mitigations",
      "Gaps, Uncertainties & Disclaimers", "Scenario Analysis", "Strategic Options",
      "Recommendations & Next Steps", "Source Map & Integrity Log"
    ];

    // Find NEXT section to process (must be sequential)
    let nextSectionToProcess = null;
    let nextSectionIndex = -1;

    // Find the first section that hasn't been approved yet
    for (let i = 0; i < allSections.length; i++) {
      if (!approvedSectionNames.includes(allSections[i])) {
        nextSectionToProcess = allSections[i];
        nextSectionIndex = i;
        break;
      }
    }

    // If we found a section that needs processing
    if (nextSectionToProcess) {
      console.log(`✅ Found Due Diligence task needing processing: "${title}" (ID: ${task.id})`);
      console.log(`Processing section: ${nextSectionToProcess} (${nextSectionIndex + 1}/20)`);

      return {
        json: {
          task_id: task.id,
          title: title.trim(),
          company_name: companyName,
          description: description.trim(),
          project_id: task.project_id || 1,
          current_section_number: nextSectionIndex,
          next_section_name: nextSectionToProcess,
          completed_sections: approvedSectionNames.length,
          approved_section_names: approvedSectionNames,
          all_sections: allSections
        }
      };
    } else {
      // All sections done, ready for final report generation
      console.log(`✅ All sections completed for task ${task.id}, creating final report`);
      return {
        json: {
          task_id: task.id,
          title: title.trim(),
          company_name: companyName,
          description: description.trim(),
          project_id: task.project_id || 1,
          current_section_number: 20,
          completed_sections: 20,
          ready_for_final_report: true,
          all_sections: allSections,
          approved_section_names: approvedSectionNames
        }
      };
    }
  }
}

// If no tasks need processing, stop gracefully
console.log('ℹ️ No Due Diligence tasks need processing - workflow completed');
throw new Error('No Due Diligence tasks need processing - workflow completed successfully');

// Prepare section data and attachments
const taskData = $('Find Due Diligence Task').first().json;
const attachments = $('Get Task Attachments').first().json.result || [];

// Define the Due Diligence report sections
const sections = [
  { "name": "Introduction & Engagement Context", "description": "Context and objectives of the due diligence process" },
  { "name": "Methodology & Reliability Levels", "description": "Approach and reliability assessment of the analysis" },
  { "name": "Company Overview", "description": "History, leadership, ownership, mission, and scale of operations" },
  { "name": "Business Model & Unit Economics", "description": "Revenue streams, cost structure, and unit economics" },
  { "name": "Products & Technology", "description": "Product offerings and technological capabilities" },
  { "name": "Target Market & Competitive Set", "description": "Market segments and competitive landscape" },
  { "name": "Financials", "description": "Multi-year financial statements, reconciled and recomputed" },
  { "name": "Cash, Burn, Runway", "description": "Cash position, burn rate, and runway analysis" },
  { "name": "Revenue Quality & Client Cohorts", "description": "Revenue composition and client segmentation" },
  { "name": "Partnerships & Ecosystem", "description": "Strategic partnerships and ecosystem integration" },
  { "name": "Intellectual Property", "description": "Patents, trademarks, and IP portfolio" },
  { "name": "Legal & Regulatory", "description": "Legal structure, compliance, and regulatory risks" },
  { "name": "Governance & Board Effectiveness", "description": "Board structure and governance practices" },
  { "name": "Capital Structure & Dilution", "description": "Capital structure and potential dilution risks" },
  { "name": "Risk Matrix & Mitigations", "description": "Key risks and mitigation strategies" },
  { "name": "Gaps, Uncertainties & Disclaimers", "description": "Identified gaps and uncertainties in the analysis" },
  { "name": "Scenario Analysis", "description": "Potential scenarios and their implications" },
  { "name": "Strategic Options", "description": "Strategic alternatives for the company" },
  { "name": "Recommendations & Next Steps", "description": "Actionable recommendations and next steps" },
  { "name": "Source Map & Integrity Log", "description": "Sources used and data integrity log" }
];

// Check if we need to create final combined report
if (taskData.ready_for_final_report) {
  console.log(`🎉 Ready to generate final combined report for company: ${taskData.company_name}`);
  return {
    json: {
      ...taskData,
      create_final_report: true,
      total_sections: sections.length,
      attachments: attachments.map(a => a.name)
    }
  };
}

// Get current section to process
const currentSectionIndex = taskData.current_section_number;
const currentSection = sections[currentSectionIndex];

if (!currentSection) {
  throw new Error(`Section index ${currentSectionIndex} is out of range. Total sections: ${sections.length}`);
}

console.log(`🎯 PROCESSING SECTION ${currentSectionIndex + 1}/${sections.length}: ${currentSection.name} for company: ${taskData.company_name}`);
console.log(`📊 Progress: ${taskData.completed_sections}/${sections.length} sections completed`);

return {
  json: {
    task_id: taskData.task_id,
    company_name: taskData.company_name,
    title: taskData.title,
    project_id: taskData.project_id,
    total_sections: sections.length,
    current_section_index: currentSectionIndex,
    current_section: currentSection,
    completed_sections: taskData.completed_sections,
    approved_section_names: taskData.approved_section_names || [],
    description: taskData.description,
    processing_single_section: true,
    attachments: attachments.map(a => a.name),
    website_url: taskData.description.match(/https?:\/\/[^\s]+/)?.[0] || 'Not available'
  }
};

// Generate final text report (not LaTeX)
const taskData = $input.first().json;

console.log(`🎉 Generating final Due Diligence report for: ${taskData.company_name}`);

// Extract approved sections from description
const description = taskData.description || '';
const sectionRegex = /📋 \*\*(.*?)\*\* - ✅ APPROVED\n\n([\s\S]*?)\n\n---/g;
const sections = [];
let match;
while ((match = sectionRegex.exec(description)) !== null) {
  sections.push({
    name: match[1],
    content: match[2].trim()
  });
}

// Create text-based report content
let reportContent = `DUE DILIGENCE REPORT\n`;
reportContent += `========================\n\n`;
reportContent += `Company: ${taskData.company_name}\n`;
reportContent += `Report Generated: ${new Date().toISOString()}\n`;
reportContent += `Sections Completed: ${sections.length}/20\n\n`;
reportContent += `========================\n\n`;

// Add sections
sections.forEach((section, index) => {
  reportContent += `${index + 1}. ${section.name}\n`;
  reportContent += `${'='.repeat(section.name.length + 3)}\n\n`;
  reportContent += `${section.content}\n\n`;
  reportContent += `------------------------\n\n`;
});

// Add executive summary
reportContent += `EXECUTIVE SUMMARY\n`;
reportContent += `=================\n\n`;
reportContent += `This comprehensive Due Diligence Report for ${taskData.company_name} was generated through a rigorous AI-powered Maker-Checker-Approver (MCA) process, ensuring accuracy and business relevance across all ${sections.length} sections.\n\n`;
reportContent += `Key Highlights:\n`;
reportContent += `- All sections validated through MCA process\n`;
reportContent += `- Data sourced from verified documents and company website\n`;
reportContent += `- Ready for executive decision-making\n\n`;
reportContent += `Report Status: COMPLETE\n`;
reportContent += `Quality Assurance: Triple-validated (Maker → Checker → Approver)\n`;

return {
  json: {
    task_id: taskData.task_id,
    company_name: taskData.company_name,
    report_content: reportContent,
    sections_count: sections.length,
    report_ready: true,
    description: taskData.description,
    attachments: taskData.attachments
  }
};

