jsonBody.prompt:
=You are the Maker agent responsible for drafting the "{{ $json.current_section.name }}" section of a Due Diligence Report.

Inputs available:
- Company name: {{ $json.company_name }}
- Company website: {{ $json.website_url }}
- PDFs from Task Attachments: {{ $json.attachments.join(', ') }}
- Financial Data: {{ $('Extract Financial Data').first().json.results || 'Not available' }}
- Outputs of previously approved sections: {{ $json.approved_section_names.join(', ') || 'None' }}

Instructions:
1. Draft the "{{ $json.current_section.name }}" section including: {{ $json.current_section.description }}.
2. Use only information from the Knowledge Base, website, financial data, or prior approved sections.
   - If missing, explicitly state: "Not available in provided materials."
3. Structure with headings and clear narrative.
4. Include inline citations pointing to the Knowledge Base sources.
5. Do not hallucinate, simulate, or invent data.

Output strictly in JSON format:
{
  "section": "{{ $json.current_section.name }}",
  "content": "... drafted text ...",
  "citations": {{ JSON.stringify($json.attachments.concat([$json.website_url])) }}
}

=You are the Checker agent. Review the Maker's draft of the "{{ $('Setup Sections').first().json.current_section.name }}" section.

Validate against the Knowledge Base:
- Company: {{ $('Setup Sections').first().json.company_name }}
- Website: {{ $('Setup Sections').first().json.website_url }}
- Attachments: {{ $('Setup Sections').first().json.attachments.join(', ') }}
- Financial Data: {{ $('Extract Financial Data').first().json.results || 'Not available' }}
- Prior Sections: {{ $('Setup Sections').first().json.approved_section_names.join(', ') || 'None' }}

Draft Content:
{{ $json.response.section }}:
{{ $json.response.content }}

Criteria:
1. Accuracy → Is the content fully supported by the Knowledge Base?
2. Hallucination → Are there claims not grounded in provided data?
3. Mock/simulated data → Are placeholders, guesses, or fabricated numbers used?
4. Completeness → Does the draft fully address the section's scope?

Output format:
{
  "decision": "approve" OR "reject",
  "feedback": "If reject, specify exact issues and what needs to be fixed."
}

parameters.functionCode:
// Process Checker response
const setupData = $('Setup Sections').first().json;
const makerContent = $('AI Maker').first().json.response;
const checkerResponse = $('AI Checker').first().json.response;

console.log(`Processing Checker response for section: ${setupData.current_section.name}`);

// Parse checker response
let checkerData;
try {
  const jsonMatch = checkerResponse.match(/\{[\s\S]*?\}/);
  if (jsonMatch) {
    checkerData = JSON.parse(jsonMatch[0]);
  } else {
    checkerData = {
      decision: "approve",
      feedback: "Content appears acceptable"
    };
  }
} catch (error) {
  console.log(`Checker JSON parsing failed: ${error.message}`);
  checkerData = {
    decision: "approve",
    feedback: "Content appears acceptable"
  };
}

console.log(`Checker result: ${checkerData.decision.toUpperCase()}`);

return {
  json: {
    ...setupData,
    maker_content: makerContent.content,
    maker_citations: makerContent.citations,
    checker_decision: checkerData.decision,
    checker_feedback: checkerData.feedback
  }
};

